const REFRESH_MS=20*60*1000,fmt=n=>new Intl.NumberFormat("en-IN").format(n??0),iso=s=>{const m=/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/.exec(s||"")||[];return [m[1],m[2],m[3]].filter((x,i)=>x||i>0).map((x,i,a)=>String(Number(x||0)).padStart(i&&a.length>1?2:1,"0")).join(":")||"0:00"},when=s=>new Date(s).toLocaleString("en-IN",{dateStyle:"medium",timeStyle:"short"});
async function load(){try{const r=await fetch(`scheduled.json?t=${Date.now()}`,{cache:"no-store"}),data=await r.json();if(!r.ok||data.error)throw new Error();const videos=data.videos||[],grid=document.getElementById("scheduledGrid"),empty=document.getElementById("scheduledEmpty");document.getElementById("scheduleCount").textContent=`${videos.length} upcoming ${videos.length===1?"video":"videos"} · checked ${when(data.syncedAt)}`;empty.style.display=videos.length?"none":"block";grid.innerHTML=videos.map(v=>`<article class="content-card"><div class="thumb"><img src="${v.thumbnail}" alt=""><span class="duration">${iso(v.duration)}</span></div><div class="card-body"><h2>${v.title}</h2><div class="card-meta"><span>Goes public ${when(v.publishAt)}</span><span class="format">Scheduled</span></div><div class="card-stats"><div><b>${fmt(v.viewCount)}</b><span>Views</span></div><div><b>${fmt(v.likeCount)}</b><span>Likes</span></div><div><b>${fmt(v.commentCount)}</b><span>Comments</span></div></div></div></article>`).join("")}catch{document.getElementById("scheduleCount").textContent="Schedule temporarily unavailable · retrying automatically"}}
const menu=document.getElementById("menuBtn"),side=document.getElementById("sidebar"),scrim=document.getElementById("scrim");menu.onclick=()=>{side.classList.toggle("open");scrim.classList.toggle("open")};scrim.onclick=()=>{side.classList.remove("open");scrim.classList.remove("open")};load();setInterval(load,REFRESH_MS);
